window.CHECKLIST_I18N = window.CHECKLIST_I18N || {};

window.CHECKLIST_I18N.fr = {

    /* ---------------- Documents & certificats ---------------- */
    'documents-0': {
        text: 'Demander le certificat PEB - obligatoire à la vente',
        why: 'Le PEB est la seule mesure objective et comparable de ce que le logement vous coûtera chaque année en énergie. En Flandre, un label E ou F s\'accompagne en plus d\'une obligation légale de rénovation vers le label D dans les 6 ans suivant l\'acte, assortie d\'amendes : un mauvais label est donc une facture future dont vous héritez, et un argument légitime pour négocier le prix.'
    },
    'documents-1': {
        text: 'Vérifier l\'attestation amiante',
        why: 'Obligatoire en Flandre à la vente pour les bâtiments antérieurs à 2001. Elle indique précisément où se trouve l\'amiante et s\'il est lié de façon sûre. Sans elle, vous achetez un risque sanitaire et un coût de rénovation inconnu : dès que vous percez, sciez ou démolissez, le retrait par une entreprise certifiée devient obligatoire.'
    },
    'documents-2': {
        text: 'Vérifier le rapport de contrôle de l\'installation électrique - valable 25 ans',
        why: 'Rapport obligatoire à la vente. S\'il indique « non conforme », vous avez 18 mois après l\'acte pour faire corriger tout ce qui y figure. Lisez le rapport lui-même, pas le résumé : un recâblage complet coûte plusieurs milliers d\'euros, et une installation dangereuse est à la fois un risque d\'incendie et un motif de réduction d\'indemnisation par l\'assureur.'
    },
    'documents-3': {
        text: 'Vérifier l\'attestation du sol - requise avant le compromis',
        why: 'Le vendeur doit la fournir avant le compromis de vente. Elle révèle si la parcelle est un site à risque connu ou présente une pollution enregistrée. L\'assainissement peut coûter plus que la maison, et les anciennes stations-service, ateliers, pressings, exploitations agricoles et citernes à mazout enterrées en sont les causes classiques.'
    },
    'documents-4': {
        text: 'Examiner l\'attestation d\'entretien du chauffage / de la chaudière',
        why: 'L\'entretien périodique est une obligation légale (en Flandre : mazout chaque année, gaz tous les 2 ans). Des attestations manquantes signifient un risque de monoxyde de carbone, une consommation plus élevée et un possible refus de votre assureur incendie. Les rapports révèlent aussi l\'âge et l\'état réels de la chaudière.'
    },
    'documents-5': {
        text: 'Vérifier le permis d\'urbanisme pour les transformations',
        why: 'Une infraction urbanistique ne se prescrit pas pour le propriétaire. Si une véranda, une extension, une lucarne ou un logement supplémentaire a été bâti sans permis, vous héritez du dossier : amende, ordre de remise en état, et des difficultés pour le crédit ou la revente. Comparez les plans du permis avec ce que vous voyez sur place.'
    },
    'documents-6': {
        text: 'Demander les informations urbanistiques',
        why: 'Elles indiquent l\'affectation de la parcelle, si la fonction résidentielle est légale, si le bien est classé, s\'il existe un plan d\'alignement (une bande à céder en cas d\'élargissement de la rue) ou une voirie projetée, et s\'il existe des infractions connues. C\'est ce qui détermine ce que vous pourrez y bâtir un jour.'
    },
    'documents-7': {
        text: 'Vérifier le risque d\'inondation (scores P et G)',
        why: 'Le vendeur doit le communiquer, mais consultez la carte officielle vous-même. Une adresse sensible aux inondations peut être difficile ou coûteuse à assurer, perdre de la valeur et limiter les extensions. Une seule inondation détruit sols, enduits, électricité et tout ce qui se trouve en cave - ne vous fiez jamais à « ici, ça n\'a jamais inondé ».'
    },
    'documents-8': {
        text: 'Demander l\'attestation de raccordement à l\'égout',
        why: 'Elle prouve que les eaux usées vont réellement à l\'égout public et non vers une fosse septique ou, pire, un fossé. Si la rue dispose d\'un réseau séparatif, le raccordement correct est votre obligation : refaire une évacuation séparée dans un jardin existant coûte facilement plusieurs milliers d\'euros.'
    },
    'documents-9': {
        text: 'Consulter les informations cadastrales du bien',
        why: 'Le plan cadastral montre ce que vous achetez réellement : les limites, la superficie et les bâtiments enregistrés. Une clôture ou un abri mal placé, ou une extension absente du plan, signale un litige de limites ou une construction non déclarée. Le revenu cadastral détermine en outre votre précompte immobilier annuel.'
    },
    'documents-10': {
        text: 'Vérifier l\'existence de servitudes',
        why: 'Un droit de passage, une allée partagée, un droit d\'écoulement ou le droit d\'un voisin à une vue sur votre jardin suit le bien indéfiniment. Ces droits peuvent bloquer une extension, une clôture ou une piscine, et ne figurent souvent que dans l\'acte - demandez-le explicitement au notaire.'
    },
    'documents-11': {
        text: 'Se renseigner sur l\'assurance logement garanti (gratuite, Flandre)',
        why: 'La Région flamande vous assure gratuitement contre la perte de revenus due au chômage, à l\'incapacité de travail ou à la cessation forcée d\'une activité indépendante, et aide à payer vos mensualités jusqu\'à 3 ans. La demande doit être introduite dans l\'année suivant le premier prélèvement du crédit - la plupart des gens n\'en entendent jamais parler et manquent le délai.'
    },
    'documents-12': {
        text: 'Consulter le Woningpas du bien (Flandre)',
        why: 'Le Woningpas rassemble les données officielles d\'un logement flamand - PEB, permis, sol, scores d\'inondation, eau et primes - dans un passeport numérique gratuit. C\'est le moyen le plus rapide de recouper ce que vous disent le vendeur et l\'agent.'
    },
    'documents-13': {
        text: 'Vérifier le nombre de logements légalement enregistrés',
        why: 'Les biens présentés comme « idéaux pour deux familles » sont souvent enregistrés comme un seul logement. Louer ou revendre un second logement non enregistré est illégal, les banques refusent souvent d\'en financer les loyers, et la régularisation peut être impossible selon les règles communales actuelles.'
    },
    'documents-14': {
        text: 'Demander les factures, garanties et dossiers techniques des travaux réalisés',
        why: 'Les factures prouvent qui a réalisé les travaux et quand, et maintiennent la responsabilité décennale de l\'entrepreneur pour les travaux structurels. Pas de facture signifie généralement du bricolage, pas de garantie, pas de recours - et souvent pas de permis non plus.'
    },

    /* ---------------- Amiante ---------------- */
    'asbestos-0': {
        text: 'Contrôler la toiture (plaques ondulées / fibrociment)',
        why: 'Les plaques ondulées en fibrociment sur les toits, garages et appentis sont l\'application d\'amiante la plus répandue en Belgique. Les plaques dégradées libèrent des fibres, que la pluie entraîne dans le sol en dessous. Elles ne peuvent être nettoyées au jet haute pression, percées ni cassées : uniquement retirées par une entreprise certifiée.'
    },
    'asbestos-1': {
        text: 'Inspecter les panneaux de plafond et sous-toitures (surtout avant 2001)',
        why: 'Les dalles de plafond tendres, les habillages de chaufferie et les panneaux de rive peuvent contenir de l\'amiante faiblement lié, bien plus dangereux que le fibrociment car les fibres se libèrent au moindre dommage. Toute rénovation du plafond devient alors un chantier spécialisé et coûteux.'
    },
    'asbestos-2': {
        text: 'Contrôler les anciens carrelages de sol et la colle noire',
        why: 'Les dalles vinyle des années 1960-1980 et la colle bitumineuse noire en dessous contiennent souvent de l\'amiante. C\'est sans danger tant que c\'est recouvert, mais poncer ou arracher libère des fibres - exactement ce que font la plupart des acheteurs dès la première semaine de travaux.'
    },
    'asbestos-3': {
        text: 'Inspecter le calorifugeage des conduites, chaudières et conduits de fumée',
        why: 'Les anciens calorifuges de conduites et les habillages de chaudière contiennent souvent de l\'amiante libre, la forme la plus dangereuse. Un calorifuge abîmé en cave contamine tout le local, et la poussière circule dans la maison sur les chaussures et les vêtements.'
    },
    'asbestos-4': {
        text: 'Contrôler seuils, conduits de ventilation et conduits de fumée en fibrociment',
        why: 'Les seuils gris en fibrociment, les gaines de ventilation et les tubages de cheminée passent facilement inaperçus, mais chacun devient un chantier de retrait certifié dès que vous remplacez les fenêtres ou installez une nouvelle évacuation de chaudière.'
    },
    'asbestos-5': {
        text: 'Inspecter les anciens tableaux électriques (fond en amiante)',
        why: 'Les tableaux à fusibles d\'avant 1980 étaient souvent montés sur des panneaux d\'amiante pour la résistance au feu. Si vous prévoyez déjà de renouveler l\'installation, faites-le intégrer au même devis plutôt que de le découvrir en cours de chantier.'
    },
    'asbestos-6': {
        text: 'Contrôler les toitures de garage, abri de jardin et carport',
        why: 'Les annexes ont reçu les matériaux les moins chers, et c\'est là que l\'amiante subsiste le plus souvent. Cela concerne aussi votre jardin : des plaques cassées contaminent le sol en dessous, ce qui devient un dossier d\'assainissement.'
    },
    'asbestos-7': {
        text: 'Vérifier le plan de retrait en cas d\'amiante - entreprise certifiée obligatoire',
        why: 'Le retrait est strictement réglementé. Le faire soi-même, ou le confier à un entrepreneur non certifié, est illégal, non assurable et contamine votre logement. Demandez un devis écrit incluant le confinement, l\'évacuation et une attestation de libération.'
    },
    'asbestos-8': {
        text: 'Prévoir un budget de désamiantage (environ 20-100 EUR/m2 plus le remplacement)',
        why: 'Les coûts varient fortement selon l\'accessibilité, le type d\'amiante et la nécessité d\'un échafaudage ou d\'un confinement. Obtenir un vrai devis avant de faire une offre transforme une inconnue angoissante en un chiffre négociable.'
    },

    /* ---------------- Extérieur ---------------- */
    'exterior-0': {
        text: 'Viser le long du faîte et du pan de toiture - est-ce parfaitement droit ?',
        why: 'Reculez et visez le long du faîte comme un menuisier vise une planche. Un creux, un affaissement, une ondulation ou une vrille signifie que la structure ne reprend plus les charges : pourriture ou vrillettes dans la panne faîtière et les chevrons (souvent après des années de petite fuite), chevrons coupés pour une lucarne ou une fenêtre de toit sans renfort, murs qui s\'écartent ou se tassent, ou surpoids dû à des tuiles plus lourdes, à l\'isolation ou à des panneaux solaires. Un creux près d\'une cheminée ou d\'une noue signale presque toujours une infiltration ancienne. La réparation d\'une charpente coûte de plusieurs milliers à plusieurs dizaines de milliers d\'euros avec échafaudage, et les assureurs traitent les fuites lentes comme un défaut d\'entretien - conditionnez donc votre offre à un rapport de couvreur ou d\'ingénieur en stabilité.'
    },
    'exterior-1': {
        text: 'Contrôler la couverture : tuiles manquantes, glissées, fissurées ou couvertes de mousse',
        why: 'Une seule tuile déplacée laisse l\'eau atteindre la sous-toiture et le bois. Une mousse épaisse retient l\'humidité contre les tuiles et accélère les dégâts du gel. Repérez les zones de couleur différente : une réparation marque en général l\'endroit d\'une ancienne fuite, où le bois en dessous peut déjà être ramolli.'
    },
    'exterior-2': {
        text: 'Vérifier l\'état de la toiture plate - très courante en Belgique',
        why: 'Les toitures plates ont une durée de vie limitée (environ 20-30 ans pour l\'EPDM, moins pour les anciens bitumes). Cloques, fissures, retrait aux relevés et stagnation d\'eau sont les signaux d\'alerte. Une toiture plate défaillante ne goutte pas sagement à un seul endroit : l\'eau circule sur le support et ressort des mètres plus loin, si bien que les dégâts sont déjà étendus quand vous les voyez.'
    },
    'exterior-3': {
        text: 'Inspecter la membrane EPDM ou bitume, les joints et les relevés',
        why: 'La plupart des fuites de toiture plate commencent à un détail, pas au milieu : une soudure, un angle, le relevé contre un mur ou la collerette autour d\'une traversée. Des bords décollés ou cassants et des réparations au mastic visibles indiquent une toiture en fin de vie, pas un petit défaut.'
    },
    'exterior-4': {
        text: 'Contrôler les coupoles / lanterneaux - relevé d\'au moins 15 cm au-dessus de l\'isolant',
        why: 'Une coupole trop basse laisse la pluie battante et la neige fondue passer par-dessus le relevé et pénétrer dans le complexe de toiture. Elle devient aussi un pont thermique qui fait goutter de la condensation sur le plafond. Si vous isolez plus tard la toiture par l\'extérieur, le relevé devra être rehaussé - un coût que l\'on oublie de budgéter.'
    },
    'exterior-5': {
        text: 'Vérifier l\'évacuation de la toiture plate - pas d\'eau stagnante 48 h après la pluie',
        why: 'L\'eau stagnante ajoute du poids, accélère le vieillissement de la membrane, fait pousser des algues et gèle en hiver, ouvrant les soudures. La stagnation signifie généralement que le support s\'est affaissé - ce qui renvoie à la structure, pas seulement à la couverture. Vérifiez aussi la présence d\'un trop-plein de sécurité.'
    },
    'exterior-6': {
        text: 'Inspecter la façade : fissures, bombements ou maçonnerie déplacée',
        why: 'Les microfissures dans les joints sont un vieillissement normal. Des fissures en escalier suivant les joints, plus larges qu\'environ 2 mm, qui s\'élargissent vers le haut ou le bas, ou une façade qui bombe vers l\'extérieur, indiquent un tassement de fondation ou une rupture d\'attache de mur creux - un problème structurel pour un ingénieur, pas pour un tube de mastic.'
    },
    'exterior-7': {
        text: 'Vérifier l\'état des joints de maçonnerie (rejointoyage)',
        why: 'Quand les joints deviennent tendres, sableux ou creux, la pluie battante pénètre la brique et le mur reste humide en permanence : facture de chauffage plus élevée, dégâts du gel et moisissures à l\'intérieur. Rejointoyer une façade moyenne représente environ 40-80 EUR/m2 avec échafaudage : une façade entière est donc un vrai poste budgétaire.'
    },
    'exterior-8': {
        text: 'Inspecter gouttières et descentes, et voir où elles se déversent',
        why: 'Une gouttière qui fuit ou déborde imbibe la même bande de façade année après année : c\'est la cause cachée classique des murs humides, des planches de rive pourries et d\'une cave humide. Cherchez la rouille, l\'affaissement, la végétation, et vérifiez que la descente est bien raccordée à une évacuation au lieu de finir au pied de la fondation.'
    },
    'exterior-9': {
        text: 'Examiner les murs extérieurs : humidité, marque de remontée ou salpêtre',
        why: 'Des dépôts blancs cristallins et une bande humide près du sol indiquent une humidité ascensionnelle - courante dans les maisons belges bâties avant la généralisation de la membrane d\'étanchéité. Elle détruit enduit et peinture, refroidit le mur, augmente les frais de chauffage et nourrit les moisissures. Une bande fraîchement peinte en bas d\'un mur est un camouflage classique.'
    },
    'exterior-10': {
        text: 'Contrôler l\'étanchéité et le fonctionnement des fenêtres et portes (PVC, bois, alu)',
        why: 'Ouvrez et fermez chacune d\'elles. Des portes et fenêtres qui coincent, ou qu\'il faut soulever pour verrouiller, trahissent souvent un châssis désaligné - donc plutôt un tassement qu\'une charnière usée. Joints en caoutchouc dégradés, bois pourri en partie basse et mastics fissurés laissent passer eau et courants d\'air.'
    },
    'exterior-11': {
        text: 'Vérifier le double ou triple vitrage et son âge',
        why: 'De la condensation entre les vitres signifie que le joint a lâché et que l\'unité doit être remplacée - elle ne se répare pas. Des intercalaires en aluminium brillant trahissent une technologie ancienne, avec bord froid et condensation sur le châssis. Un mauvais vitrage coûte de l\'énergie, provoque des courants d\'air et des moisissures sur les ébrasements, et dégrade le label PEB.'
    },
    'exterior-12': {
        text: 'Vérifier l\'isolation du mur creux et l\'état de la coulisse',
        why: 'Une coulisse non isolée est l\'un des gains énergétiques les moins chers qui soient (injection), mais uniquement si elle est propre, assez large et exempte de coulures de mortier et d\'humidité. Repérez la grille caractéristique de trous rebouchés pour savoir si c\'est déjà fait - et demandez l\'attestation, car une injection mal faite crée des ponts d\'humidité.'
    },
    'exterior-13': {
        text: 'Contrôler la fondation et le soubassement : fissures, dégâts d\'eau, absence de membrane',
        why: 'Le soubassement est l\'endroit où le sol rencontre le mur et où commence l\'humidité ascensionnelle. Cherchez une membrane d\'étanchéité visible, et vérifiez si de la terre, un pavage de terrasse ou un massif surélevé se trouve AU-DESSUS de ce niveau - une cause très fréquente et très facilement manquée de murs chroniquement humides.'
    },
    'exterior-14': {
        text: 'Inspecter les briques : dégâts de gel et faces qui s\'écaillent',
        why: 'Des faces de brique qui s\'écaillent ou s\'effritent signifient que l\'eau est absorbée puis gèle à l\'intérieur de la brique. Cela empire chaque hiver, expose le cœur plus tendre de la brique, et signale généralement un problème d\'humidité sous-jacent comme une gouttière qui fuit ou des joints dégradés.'
    },
    'exterior-15': {
        text: 'Vérifier le drainage et le niveau du sol autour de la fondation',
        why: 'Le sol et les revêtements doivent s\'écarter de la maison en pente. Quand une terrasse, une allée ou un jardin se trouve plus haut que la membrane d\'étanchéité, la pluie coule vers le mur et pénètre la structure - très bon marché à vérifier, très cher à découvrir plus tard.'
    },
    'exterior-16': {
        text: 'Vérifier l\'étanchéité et la pente de la terrasse ou du balcon',
        why: 'Un balcon au-dessus d\'un espace habité est une toiture. Si la pente, l\'étanchéité ou le détail de rive est incorrect, l\'eau pénètre la dalle, corrode les armatures et fait éclater le béton - l\'une des réparations les plus coûteuses d\'un immeuble, et souvent une charge commune.'
    },
    'exterior-17': {
        text: 'Inspecter la cheminée - enduit, solins, plomberie de couverture et couronnement',
        why: 'La cheminée est la partie la plus exposée du bâtiment et le point de fuite le plus fréquent. Enduit fissuré, joints ouverts et solins défaillants laissent l\'eau pénétrer la souche : elle descend ensuite à l\'intérieur du mur et ressort en tache sur un plafond de chambre, sans rien évoquer d\'une fuite de toiture.'
    },
    'exterior-18': {
        text: 'Vérifier les lucarnes et fenêtres de toit et leurs raccords d\'étanchéité',
        why: 'Lucarnes et fenêtres de toit sont découpées dans la charpente : ce sont à la fois un point de fuite fréquent et un endroit où des chevrons ont souvent été coupés sans chevêtre correct. Des traces d\'humidité autour, dans le grenier, racontent les deux histoires à la fois.'
    },
    'exterior-19': {
        text: 'Examiner le jardin : arbres proches du bâtiment, murs de clôture et clôtures mitoyennes',
        why: 'De grands arbres près d\'une façade peuvent affecter la fondation par retrait des sols argileux et par pression racinaire, et remplissent vos gouttières chaque automne. Murs, haies et clôtures sont une source classique de conflits de voisinage - découvrez qui les possède et les entretient avant l\'achat, pas après.'
    },
    'exterior-20': {
        text: 'Vérifier la présence d\'une citerne d\'eau de pluie, sa capacité et sa pompe',
        why: 'Une citerne est souvent obligatoire en construction neuve et en rénovation lourde, et réduit votre facture d\'eau. Vérifiez qu\'elle est réellement raccordée aux WC et aux robinets extérieurs, que la pompe fonctionne et que le trop-plein s\'évacue légalement : beaucoup de citernes sont posées puis jamais raccordées.'
    },

    /* ---------------- Cuisine ---------------- */
    'kitchen-0': {
        text: 'Tester tous les appareils (four, taques, lave-vaisselle, frigo)',
        why: 'Les appareils encastrés font généralement partie de la vente et sont généralement ce qu\'il y a de plus vieux dans la cuisine. Remplacer un four, une taque et un lave-vaisselle intégrés coûte facilement 1 500 à 3 000 EUR, et une dimension non standard peut vous obliger à changer toute une rangée de meubles.'
    },
    'kitchen-1': {
        text: 'Vérifier la présence d\'un raccordement au gaz et sa conformité',
        why: 'Un raccordement au gaz doit être étanche et le local suffisamment ventilé. Les flexibles portent une date de péremption. Si vous voulez passer à l\'induction, sachez que cela demande un circuit dédié puissant, et parfois un raccordement plus fort.'
    },
    'kitchen-2': {
        text: 'Vérifier que la cuisine dispose de ses propres circuits électriques',
        why: 'La cuisine tire la charge continue la plus élevée de la maison. Faire fonctionner four, lave-vaisselle et bouilloire sur un seul vieux circuit fait disjoncter en permanence et surchauffe le câblage. Dans les maisons anciennes, tout un étage dépend souvent d\'un seul circuit de 16 A : un coût de recâblage à connaître d\'avance.'
    },
    'kitchen-3': {
        text: 'Contrôler le plan de travail : matériau, joints et état autour de l\'évier',
        why: 'Un panneau de particules gonflé, foncé ou mou au niveau de la découpe de l\'évier signifie que l\'eau s\'infiltre depuis longtemps. C\'est le premier point de rupture d\'une cuisine, et cela implique généralement de remplacer aussi le joint de l\'évier et le meuble en dessous.'
    },
    'kitchen-4': {
        text: 'Regarder sous l\'évier : fuites, taches ou dégâts d\'eau',
        why: 'Ouvrez le meuble et touchez le fond. Un panneau gondolé, une odeur de moisi ou un fond suspicieusement neuf trahissent une fuite lente. Les fuites lentes pourrissent le plancher et peuvent atteindre les solives : un siphon à 50 EUR devient une réparation de plancher.'
    },
    'kitchen-5': {
        text: 'Vérifier la hotte et si elle évacue vers l\'extérieur',
        why: 'Une hotte à recyclage avec filtre à charbon élimine les odeurs mais pas l\'humidité : toute la vapeur de cuisson reste dans la maison et se condense ailleurs, là où c\'est plus froid. Raccorder une hotte vers l\'extérieur après coup implique de percer un mur ou une toiture : vérifiez-le avant de vous engager.'
    },
    'kitchen-6': {
        text: 'Tester toutes les prises - type étanche aux projections requis près de l\'évier',
        why: 'Des prises trop proches d\'un évier ou d\'une taque constituent à la fois une infraction et un vrai risque d\'électrocution. Elles figureront aussi au rapport de contrôle électrique : leur mise en conformité deviendra votre obligation.'
    },
    'kitchen-7': {
        text: 'Contrôler carrelages, joints et silicones - sol et murs',
        why: 'Des joints fissurés et des silicones noircis laissent l\'eau passer derrière le carrelage, où elle imbibe l\'enduit et le support. Un carrelage qui sonne creux a déjà perdu son adhérence : la réparation est bien plus lourde qu\'il n\'y paraît.'
    },
    'kitchen-8': {
        text: 'Inspecter les meubles, charnières et coulisses de tiroirs',
        why: 'Des portes qui ne s\'alignent plus, des étagères affaissées et des chants gonflés montrent une cuisine en fin de vie. Une cuisine complète représente généralement 5 000 à 20 000 EUR : cela influence directement la valeur du bien à vos yeux.'
    },
    'kitchen-9': {
        text: 'Vérifier l\'éclairage au-dessus des plans de travail',
        why: 'Un seul plafonnier signifie que vous travaillez toujours dans votre propre ombre, ce qui est réellement dangereux avec des couteaux et des casseroles chaudes. Ajouter un éclairage sous meubles plus tard implique de nouveaux câbles dans un mur fini.'
    },
    'kitchen-10': {
        text: 'Contrôler l\'emplacement lave-linge / lave-vaisselle : arrivée d\'eau, évacuation et sol étanche',
        why: 'Un appareil à l\'étage sans bac étanche ni siphon de sol finira par inonder le plafond du dessous. Vérifiez que la hauteur d\'évacuation est correcte et qu\'il existe une vanne d\'arrêt réellement accessible.'
    },
    'kitchen-11': {
        text: 'Contrôler l\'évier, le robinet et la pression d\'eau',
        why: 'Un débit faible peut venir d\'un aérateur entartré, mais tout autant de conduites entartrées ou sous-dimensionnées, ou d\'une ancienne alimentation en plomb. Ouvrez l\'eau chaude et comptez les secondes : une longue attente signale un chauffe-eau éloigné ou sous-dimensionné.'
    },
    'kitchen-12': {
        text: 'Vérifier si l\'implantation peut changer sans déplacer les évacuations',
        why: 'Déplacer un évier ou un lave-vaisselle de quelques mètres exige une nouvelle évacuation avec la bonne pente. Dans une dalle en béton, cela veut dire casser le sol. Le savoir d\'avance, c\'est la différence entre un rafraîchissement à 2 000 EUR et une rénovation à 15 000 EUR.'
    },

    /* ---------------- Salle de bain ---------------- */
    'bathroom-0': {
        text: 'Tester la chasse du WC et vérifier les fuites à la base',
        why: 'Un réservoir qui coule en continu gaspille discrètement des milliers de litres par an. De l\'eau ou une auréole sombre à la base signifie que le joint a lâché et que l\'eau atteint la structure du plancher : une cause fréquente de solives pourries dans les maisons anciennes.'
    },
    'bathroom-1': {
        text: 'Contrôler pression, débit et stabilité de température de la douche',
        why: 'Faites couler la douche puis ouvrez un autre robinet. Une forte variation de pression ou de température indique des conduites sous-dimensionnées ou une chaudière trop faible : agaçant tous les jours et coûteux à corriger une fois les murs carrelés.'
    },
    'bathroom-2': {
        text: 'Vérifier la vitesse d\'évacuation de la douche et de la baignoire',
        why: 'Une évacuation lente signale un bouchon partiel, une pente insuffisante ou une évacuation sous-dimensionnée. De l\'eau qui stagne dans un receveur signifie que celui-ci ou le sol s\'est affaissé : bien plus qu\'une affaire de ventouse.'
    },
    'bathroom-3': {
        text: 'Vérifier l\'étanchéité sous et derrière les carrelages',
        why: 'Le carrelage et les joints ne sont pas étanches ; la membrane derrière l\'est. Les salles de bain belges antérieures à 2000 environ n\'en ont souvent aucune. Dès que l\'eau passe derrière, elle imbibe la chape, pourrit le plancher et apparaît en tache au plafond du dessous - la seule vraie solution est de casser la salle de bain.'
    },
    'bathroom-4': {
        text: 'Vérifier la présence d\'une ventilation mécanique et qu\'elle extrait réellement',
        why: 'Placez une feuille de papier contre la grille : elle doit tenir. Une salle de bain sans extraction efficace produit des litres de vapeur par douche, qui se condensent sur les surfaces froides et créent des moisissures noires en un seul hiver - un problème de santé autant qu\'esthétique.'
    },
    'bathroom-5': {
        text: 'Inspecter carrelages, joints et silicones : fissures et moisissures',
        why: 'Un silicone noirci ou friable au bord de la baignoire et de la douche est la première porte d\'entrée de l\'eau. Un carrelage qui sonne creux a perdu son adhérence. C\'est bon marché à corriger maintenant et très cher une fois le plancher touché.'
    },
    'bathroom-6': {
        text: 'Tester le lavabo, le robinet et le siphon en dessous',
        why: 'Remplissez le lavabo et laissez-le se vider entièrement en regardant dessous : beaucoup de fuites n\'apparaissent qu\'à plein débit. Un siphon absent ou asséché laisse aussi remonter les odeurs d\'égout.'
    },
    'bathroom-7': {
        text: 'Vérifier que prises et appareils respectent les volumes de sécurité',
        why: 'La réglementation belge définit des volumes de protection autour de la baignoire et de la douche. Prises et interrupteurs situés dans ces volumes sont dangereux et seront relevés au rapport de contrôle, rendant leur correction obligatoire après l\'achat.'
    },
    'bathroom-8': {
        text: 'Vérifier que l\'éclairage convient aux locaux humides (indice IP près de la douche)',
        why: 'Un luminaire ordinaire se corrode dans une salle de bain et peut se retrouver sous tension. Des vis rouillées ou de la condensation à l\'intérieur d\'un luminaire sont des signes visibles qu\'un mauvais produit a été posé.'
    },
    'bathroom-9': {
        text: 'Contrôler la pente du sol vers l\'évacuation',
        why: 'Si l\'eau stagne au lieu de rejoindre l\'évacuation, la chape est mal réalisée. Dans une douche à l\'italienne, cela signifie des joints en permanence humides, des moisissures et à terme de l\'eau dans la structure - et corriger une pente implique de démolir le sol.'
    },
    'bathroom-10': {
        text: 'Chercher moisissures, peinture écaillée et dégâts d\'humidité aux murs et au plafond',
        why: 'Des moisissures dans les angles et au plafond sont un problème de ventilation ; une tache localisée est une fuite. La distinction compte : l\'un se règle avec un ventilateur, l\'autre avec un plombier. Les spores aggravent aussi l\'asthme et les allergies : ce n\'est pas qu\'une tache.'
    },
    'bathroom-11': {
        text: 'Tester le sèche-serviettes et le radiateur',
        why: 'Une salle de bain froide reste humide des heures après la douche, et c\'est exactement ainsi que les moisissures s\'installent. Un radiateur froid en haut demande généralement une purge, mais s\'il reste froid entièrement, il peut être isolé du circuit.'
    },
    'bathroom-12': {
        text: 'Vérifier que les évacuations et vannes d\'arrêt restent accessibles',
        why: 'Des conduites noyées derrière le carrelage sans trappe de visite transforment toute fuite future en démolition. Repérez aussi la vanne d\'arrêt locale : si la seule vanne est celle de toute la maison, un flexible qui lâche devient un événement bien plus grave.'
    },

    /* ---------------- Chambre ---------------- */
    'bedroom-0': {
        text: 'Contrôler toutes les prises - nombre, emplacement et mise à la terre',
        why: 'Deux prises par chambre, c\'est des rallonges partout : peu pratique et à risque d\'incendie. Des prises non reliées à la terre dans une pièce trahissent un câblage ancien dans toute la maison : traitez cela comme un signal, pas comme un détail.'
    },
    'bedroom-1': {
        text: 'Tester les interrupteurs et les luminaires',
        why: 'Des interrupteurs qui clignotent, bourdonnent ou chauffent signalent des connexions desserrées - un vrai risque d\'incendie dans les installations anciennes. Vérifiez aussi s\'il existe un va-et-vient entre la porte et le lit : en ajouter un plus tard implique de saigner un mur.'
    },
    'bedroom-2': {
        text: 'Inspecter l\'espace de rangement et le fonctionnement des portes de placard',
        why: 'Un placard encastré contre un mur extérieur non isolé emprisonne de l\'air froid et immobile : c\'est un endroit classique pour trouver des moisissures derrière. Écartez-le du mur si possible et regardez.'
    },
    'bedroom-3': {
        text: 'Contrôler les fenêtres : fonctionnement, étanchéité et grilles de ventilation',
        why: 'Une chambre a besoin d\'un apport d\'air contrôlé : deux adultes expirent environ un litre de vapeur d\'eau par nuit. Une fenêtre qui ne s\'ouvre pas, ou une grille scotchée, signifie que cette humidité reste dans la pièce et se dépose sur le mur le plus froid.'
    },
    'bedroom-4': {
        text: 'Examiner les murs : fissures, taches ou zones humides',
        why: 'Les fissures qui partent en diagonale des angles de fenêtres et de portes signalent un tassement. Les zones humides sur un mur extérieur derrière un meuble relèvent généralement de la condensation due à une mauvaise isolation, pas d\'une fuite - mais il faut comprendre les deux avant de repeindre.'
    },
    'bedroom-5': {
        text: 'Inspecter l\'état du sol - parquet, stratifié, moquette',
        why: 'Un sol souple ou en pente signale un problème de solives ; une forte odeur venant d\'une vieille moquette masque souvent des dégâts d\'animaux ou de l\'humidité en dessous. Soulevez un coin si possible : ce qu\'il y a sous le revêtement compte plus que le revêtement.'
    },
    'bedroom-6': {
        text: 'Contrôler le plafond : taches, affaissement ou retouches de peinture fraîches',
        why: 'Une tache aux bords bruns est une trace d\'eau ; une seule zone fraîchement peinte sur un plafond par ailleurs ancien signifie généralement que quelqu\'un a recouvert quelque chose. Demandez directement quelle en était la cause et quand la réparation a eu lieu.'
    },
    'bedroom-7': {
        text: 'Tester le chauffage de la pièce - radiateur ou chauffage au sol',
        why: 'Un radiateur froid en bas est embouché ; froid en haut, il faut simplement le purger. Une pièce sans aucune source de chaleur est un vrai problème de confort et de normes de qualité du logement, et ajouter un radiateur implique de prolonger la tuyauterie.'
    },
    'bedroom-8': {
        text: 'Vérifier le détecteur de fumée : présence, emplacement et date',
        why: 'Obligatoire en Flandre à chaque niveau du logement. Les détecteurs expirent (généralement après 10 ans, la date figure sur le boîtier) et un détecteur périmé équivaut à une absence de détecteur. Appuyez sur le bouton test pendant la visite.'
    },
    'bedroom-9': {
        text: 'Vérifier la ventilation et si les grilles ne sont pas obstruées',
        why: 'Des grilles scotchées, repeintes ou bourrées de chiffons indiquent fortement que les occupants luttaient contre les courants d\'air ou le bruit - et que l\'humidité n\'avait nulle part où aller. Cette humidité est désormais quelque part dans la construction.'
    },
    'bedroom-10': {
        text: 'Évaluer l\'isolation acoustique : rue, voisins et cage d\'escalier',
        why: 'Le bruit est ce que les acheteurs regrettent le plus après le déménagement et ce qui est le plus difficile à corriger. Restez immobile en silence pendant la visite et, si possible, revenez une fois le soir et une fois aux heures de pointe.'
    },

    /* ---------------- Séjour ---------------- */
    'livingroom-0': {
        text: 'Contrôler toutes les prises - nombre, répartition et mise à la terre',
        why: 'Un séjour a besoin de prises sur plusieurs murs ; les pièces belges anciennes en ont souvent deux. En ajouter implique de saigner l\'enduit et de repeindre : comptez-les maintenant et intégrez ce travail à votre offre.'
    },
    'livingroom-1': {
        text: 'Tester les interrupteurs et les luminaires',
        why: 'Des interrupteurs qui bourdonnent ou chauffent signalent des connexions desserrées et un risque d\'incendie. Vérifiez aussi si les circuits d\'éclairage sont commandés logiquement : une commutation mal pensée est une gêne quotidienne et coûteuse à modifier après coup.'
    },
    'livingroom-2': {
        text: 'Inspecter le feu ouvert ou le poêle et demander l\'attestation du conduit',
        why: 'Un conduit non tubé ou fissuré peut laisser du monoxyde de carbone entrer dans la pièce et constitue un risque d\'incendie sérieux. Demandez quand la cheminée a été ramonée et si l\'appareil dispose d\'une attestation de conformité ; sans elle, votre assurance incendie peut être contestée.'
    },
    'livingroom-3': {
        text: 'Contrôler les fenêtres, le type de vitrage et l\'orientation',
        why: 'De grandes fenêtres en simple vitrage ou en double vitrage ancien dominent la facture de chauffage et le confort de la pièce. Un vitrage orienté sud ou ouest provoque aussi de fortes surchauffes en été s\'il n\'y a pas de protection solaire - un sujet de plus en plus pertinent en Belgique.'
    },
    'livingroom-4': {
        text: 'Examiner les murs : fissures ou bombements',
        why: 'Des fissures près d\'une souche de cheminée, d\'une baie ou là où un mur a été supprimé peuvent indiquer qu\'un élément porteur a été modifié sans poutre correcte. C\'est une question pour un ingénieur en stabilité, pas pour le peintre.'
    },
    'livingroom-5': {
        text: 'Inspecter l\'état et la planéité du sol (parquet, carrelage, stratifié)',
        why: 'Posez une bille ou un niveau sur le sol. Une pente marquée, un plancher souple ou des joints qui s\'ouvrent entre les lames signalent un mouvement de solives ou de fondation plutôt qu\'une simple usure.'
    },
    'livingroom-6': {
        text: 'Contrôler la hauteur sous plafond et les proportions pour l\'habitabilité',
        why: 'Les normes de qualité du logement imposent des hauteurs minimales pour qu\'une pièce compte comme espace de vie. Cela détermine aussi si vous pourrez un jour isoler le sol ou poser un faux plafond sans rendre la pièce oppressante.'
    },
    'livingroom-7': {
        text: 'Tester le chauffage - radiateurs ou chauffage au sol',
        why: 'Touchez chaque radiateur en haut et en bas. Des radiateurs sous-dimensionnés dans la plus grande pièce signifient que la maison ne sera jamais vraiment chaude par grand froid, et les remplacer peut aussi exiger une chaudière plus puissante ou des conduites plus grosses.'
    },
    'livingroom-8': {
        text: 'Vérifier internet, TV et réseau, ainsi que le débit disponible à l\'adresse',
        why: 'La couverture fibre en Belgique varie d\'une rue à l\'autre. Vérifiez la technologie et le débit réellement disponibles à l\'adresse exacte avant d\'acheter : télétravailler avec une connexion lente est un problème quotidien qu\'aucune rénovation ne résout.'
    },
    'livingroom-9': {
        text: 'Évaluer la lumière naturelle, l\'orientation et les ombres portées',
        why: 'Un séjour orienté nord avec un immeuble voisin élevé demandera de la lumière artificielle toute la journée et paraîtra toujours froid. Notez l\'orientation et l\'heure de votre visite : une visite à 10 h ne dit rien de la soirée.'
    },
    'livingroom-10': {
        text: 'Chercher les signes d\'un mur supprimé ou d\'une ouverture agrandie',
        why: 'Les séjours ouverts dans les maisons belges anciennes ont souvent été créés en supprimant un mur porteur. Si cela s\'est fait sans poutre correctement dimensionnée ni permis, vous verrez des fissures au-dessus de l\'ouverture et des plafonds qui s\'affaissent - et vous héritez de la responsabilité.'
    },

    /* ---------------- Cave ---------------- */
    'basement-0': {
        text: 'Vérifier l\'humidité ou une infiltration d\'eau active',
        why: 'La cave est la partie la plus honnête de la maison : ce que fait le sol s\'y voit en premier. Des marques d\'eau à hauteur constante indiquent des inondations périodiques ; des zones humides sur un seul mur, une infiltration extérieure. Un cuvelage intérieur coûte généralement plusieurs milliers d\'euros et n\'est pas toujours définitif.'
    },
    'basement-1': {
        text: 'Inspecter les murs à la recherche de salpêtre (efflorescences blanches)',
        why: 'Ces cristaux blancs sont des sels extraits de la brique par l\'eau qui s\'évapore. Ils prouvent qu\'une humidité circule activement dans le mur et détruisent lentement enduit et mortier. Les brosser ne change rien à la cause.'
    },
    'basement-2': {
        text: 'Se fier à l\'odeur - une odeur de moisi signale une humidité persistante',
        why: 'Votre nez est un bon humidimètre. Une forte odeur de terre ou de moisi signifie que l\'humidité est suffisante pour que des moisissures se développent, même si les murs semblent secs - et cette odeur remonte dans la maison par la cage d\'escalier.'
    },
    'basement-3': {
        text: 'Vérifier si la cave est légalement habitable',
        why: 'Transformer une cave en chambre ou en bureau exige une hauteur minimale, de la lumière naturelle, des issues et une ventilation, et généralement un permis. Beaucoup de « pièces supplémentaires » en cave ne sont pas conformes, ce qui affecte l\'assurance et la revente.'
    },
    'basement-4': {
        text: 'Mesurer la hauteur sous plafond en vue d\'un usage futur',
        why: 'Si vous ajoutez ensuite une isolation de sol et une chape, vous perdez 10 à 15 cm, et un système de cuvelage sur les murs en prend encore. Mesurez avant de planifier : beaucoup d\'aménagements de cave échouent rien que sur la hauteur.'
    },
    'basement-5': {
        text: 'Inspecter les murs de fondation : fissures, bombements ou briques déplacées',
        why: 'Des fissures horizontales ou un mur qui bombe vers l\'intérieur signalent une poussée des terres et sont bien plus graves que des fissures verticales de retrait. C\'est l\'un des rares constats qui doit suspendre un achat tant qu\'un ingénieur n\'a pas regardé.'
    },
    'basement-6': {
        text: 'Vérifier si les murs ont été cuvelés, et comment',
        why: 'Un enduit récent, une couche d\'étanchéité brillante ou une contre-cloison neuve dans une vieille cave masquent souvent un problème d\'humidité plutôt qu\'ils ne le résolvent. Étanchéifier l\'intérieur peut même repousser l\'humidité plus haut dans le mur. Demandez la facture et la garantie.'
    },
    'basement-7': {
        text: 'Contrôler le système de drainage et une éventuelle pompe de relevage',
        why: 'Si la cave ne reste sèche que grâce à une pompe, il faut le savoir : les pompes tombent en panne, et précisément pendant l\'orage où vous en avez besoin. Vérifiez qu\'elle fonctionne, qu\'il existe une alarme ou un secours, et demandez à quelle fréquence elle tourne réellement.'
    },
    'basement-8': {
        text: 'Chercher moisissures sur les murs, le bois et les objets stockés',
        why: 'Des moisissures en cave signifient une humidité chroniquement élevée. Les spores remontent dans la maison et aggravent asthme et allergies. Cela indique aussi que tout le bois présent - solives, escalier, huisseries - risque de pourrir.'
    },
    'basement-9': {
        text: 'Contrôler l\'isolation et le calorifugeage si la cave est chauffée ou sous un espace habité',
        why: 'Un plafond de cave non isolé rend le rez-de-chaussée durablement froid et augmente les frais de chauffage. C\'est souvent l\'un des travaux d\'isolation les moins chers et les plus efficaces dans une maison existante - à condition que la cave soit sèche.'
    },
    'basement-10': {
        text: 'Inspecter le sol - état du béton, fissures et étanchéité',
        why: 'Les caves anciennes n\'ont souvent aucune dalle, juste de la terre battue ou une chape fine, si bien que l\'humidité du sol s\'évapore directement dans le local. Une humidité qui remonte par le sol ne se règle pas en traitant les murs.'
    },
    'basement-11': {
        text: 'Vérifier la présence de grilles de ventilation non obstruées',
        why: 'Les soupiraux sont souvent murés ou bloqués par une terrasse construite plus tard. Sans mouvement d\'air, l\'humidité reste durablement élevée, et toute isolation ajoutée ensuite emprisonne l\'humidité dans la construction.'
    },
    'basement-12': {
        text: 'Contrôler la chaufferie : accès, ventilation et stockage de combustible',
        why: 'Un appareil à combustion a besoin d\'un apport d\'air permanent ; boucher cette grille contre les courants d\'air crée un risque de monoxyde de carbone. Vérifiez aussi la présence d\'une ancienne citerne à mazout : une citerne hors service doit être vidée, nettoyée et certifiée, et une citerne qui fuit devient un dossier de pollution du sol.'
    },
    'basement-13': {
        text: 'Vérifier que l\'installation électrique de la cave respecte les normes actuelles',
        why: 'Les caves sont des locaux humides où un câblage ancien, non isolé ou bricolé est fréquent et réellement dangereux. C\'est aussi là que se trouvent généralement le compteur et le tableau : cela vous renseigne d\'emblée sur l\'ensemble de l\'installation.'
    },

    /* ---------------- Grenier ---------------- */
    'attic-0': {
        text: 'Contrôler l\'isolation de toiture - présence, type et épaisseur',
        why: 'L\'isolation de toiture est la plus grande économie de chaleur dans une maison belge et le moyen le moins cher d\'améliorer le label PEB. Notez l\'épaisseur (aujourd\'hui, généralement 20 à 30 cm de laine minérale) et la présence d\'un pare-vapeur côté chaud : une isolation sans pare-vapeur provoque de la condensation dans la toiture.'
    },
    'attic-1': {
        text: 'Chercher la lumière du jour, les taches d\'eau et les coulées sombres sous la toiture',
        why: 'Montez par temps clair et éteignez la lumière. Des points de jour signalent des tuiles manquantes ou une sous-toiture déchirée. Des coulées sombres le long des chevrons tracent exactement le chemin de l\'eau, ce qui vous indique où regarder à l\'extérieur.'
    },
    'attic-2': {
        text: 'Inspecter la charpente (chevrons, pannes, faîtière) : affaissement ou flexion',
        why: 'C\'est la vue intérieure de la ligne de faîte que vous avez observée depuis la rue. Repérez les chevrons qui fléchissent, les assemblages ouverts, les étais ajoutés par un ancien propriétaire, et le bois coupé pour une lucarne ou une fenêtre de toit sans chevêtre correct. Les interventions amateurs sur une charpente sont fréquentes et peuvent être dangereuses.'
    },
    'attic-3': {
        text: 'Chercher les traces de vrillettes, de pourriture ou de champignons',
        why: 'De petits trous ronds avec de la sciure fine en dessous signalent une infestation active ; un bois mou, friable ou fibreux signale une pourriture, qui est toujours d\'abord un problème d\'humidité. Enfoncez un tournevis dans le bois suspect : s\'il s\'enfonce, le bois a perdu sa résistance. Traitement plus remplacement du bois représente un coût sérieux.'
    },
    'attic-4': {
        text: 'Vérifier si le plancher peut supporter une charge d\'habitation',
        why: 'Les solives de plafond ne sont généralement dimensionnées que pour un plafond et un stockage léger, pas pour des personnes et des meubles. Aménager un grenier impose souvent de renforcer ou remplacer le plancher : un travail d\'ingénieur, et l\'un des plus gros coûts cachés d\'un aménagement.'
    },
    'attic-5': {
        text: 'Mesurer la hauteur utile et la surface exploitable pour un aménagement',
        why: 'Les règles d\'habitabilité exigent une hauteur minimale sur une proportion minimale du sol. Mesurez au faîte et à l\'endroit où la pente atteint 1,5 m : c\'est la surface réellement utilisable, généralement bien plus petite qu\'elle n\'en a l\'air.'
    },
    'attic-6': {
        text: 'Vérifier si l\'aménagement est légalement possible (permis, lumière, issue de secours)',
        why: 'Une chambre sous combles exige un permis, un éclairage naturel suffisant, une ventilation et une issue de secours. Acheter une maison « parce qu\'on pourra toujours aménager le grenier » sans vérifier ces règles est l\'une des suppositions les plus coûteuses qu\'un acheteur puisse faire.'
    },
    'attic-7': {
        text: 'Contrôler la ventilation du comble et au-dessus de l\'isolant',
        why: 'Une toiture froide a besoin d\'une lame d\'air au-dessus de l\'isolant pour évacuer l\'humidité venant du logement. La boucher - en tassant l\'isolant contre la sous-toiture - provoque condensation, isolant détrempé et pourriture des chevrons, souvent en deux ou trois hivers.'
    },
    'attic-8': {
        text: 'Inspecter le câblage électrique du grenier',
        why: 'Le câblage du grenier est généralement le plus ancien de la maison et se retrouve souvent enfoui sous une isolation ajoutée plus tard, où les câbles surchauffent. Y trouver du câble sous tissu ou cassant est un indicateur fort que toute l\'installation doit être renouvelée.'
    },
    'attic-9': {
        text: 'Vérifier l\'état de la cheminée depuis l\'intérieur du comble',
        why: 'Depuis le grenier, vous voyez si la souche est fissurée, si le mortier s\'effrite et s\'il y a des traces d\'humidité autour. Les cheminées sont le point de fuite le plus fréquent, et des traces ici expliquent les taches de plafond dans les pièces du dessous.'
    },
    'attic-10': {
        text: 'Vérifier si des fenêtres de toit ou une lucarne peuvent être ajoutées',
        why: 'Les fenêtres de toit sont souvent dispensées de permis alors que les lucarnes ne le sont généralement pas, et les règles communales sur les pans de toiture visibles varient fortement. Cela détermine si le grenier pourra devenir une vraie pièce : vérifiez auprès de la commune, pas de l\'agent immobilier.'
    },
    'attic-11': {
        text: 'Chercher des traces d\'oiseaux, guêpes, rongeurs ou fouines',
        why: 'Déjections, nids, isolant rongé et câbles mordillés sont fréquents dans les greniers belges. Au-delà de la saleté, fouines et rongeurs endommagent câbles et isolation, et leurs points d\'entrée sont les mêmes ouvertures qui laissent passer l\'eau.'
    },

    /* ---------------- Eau & sanitaires ---------------- */
    'plumbing-0': {
        text: 'Localiser et manœuvrer la vanne d\'arrêt principale',
        why: 'Le jour où un flexible éclate, vous avez des secondes, pas des minutes. Les vieilles vannes se grippent en position ouverte et cassent au moment où vous en avez besoin. Trouvez-la, vérifiez qu\'elle tourne, et assurez-vous qu\'elle est accessible sans déplacer de meubles.'
    },
    'plumbing-1': {
        text: 'Tester la pression d\'eau - environ 2 à 4 bar est normal',
        why: 'Une pression trop basse donne des douches faibles et des appareils qui se remplissent lentement ; trop haute (au-delà d\'environ 5 bar), elle fatigue joints, flexibles et chaudière et provoque des coups de bélier. Un manomètre sur un robinet extérieur coûte une dizaine d\'euros et répond immédiatement.'
    },
    'plumbing-2': {
        text: 'Inspecter les conduites - repérer toute conduite d\'alimentation en plomb',
        why: 'Les conduites en plomb sont gris terne, assez tendres pour être rayées avec une pièce de monnaie et sonnent mat. Le plomb se dissout dans l\'eau potable et représente un risque sérieux pour les enfants et les femmes enceintes. Le remplacement n\'est pas optionnel : budgétez-le et utilisez-le dans la négociation.'
    },
    'plumbing-3': {
        text: 'Identifier le matériau des conduites (cuivre, PVC, multicouche, acier galvanisé)',
        why: 'L\'acier galvanisé s\'entartre de l\'intérieur et finit par réduire le débit à un filet ; raccorder directement cuivre et acier provoque une corrosion galvanique. Connaître le matériau vous indique la durée de vie restante du réseau, pas seulement son comportement actuel.'
    },
    'plumbing-4': {
        text: 'Vérifier l\'âge, le type et la capacité du chauffe-eau',
        why: 'Lisez la plaque signalétique : l\'année figure généralement dans le numéro de série. Un chauffe-eau dure environ 10 à 15 ans, et un modèle sous-dimensionné signifie plus d\'eau chaude après deux douches. Le remplacement représente 1 500 à 4 000 EUR à anticiper.'
    },
    'plumbing-5': {
        text: 'Vérifier s\'il y a une chaudière à condensation et comment le condensat s\'évacue',
        why: 'Les chaudières à condensation sont bien plus efficaces mais exigent une évacuation des condensats et un conduit adapté. Si un ancien propriétaire en a posé une sans évacuation correcte, le condensat acide a abîmé quelque chose. Cela conditionne aussi une future mise à niveau.'
    },
    'plumbing-6': {
        text: 'Tester le délai et la température d\'eau chaude au robinet le plus éloigné',
        why: 'Une longue attente gaspille des litres chaque jour et signale des conduites non calorifugées ou mal tracées. Une eau stockée sous 60 °C environ présente en outre un risque de légionelle dans les installations plus grandes.'
    },
    'plumbing-7': {
        text: 'Inspecter le raccordement à l\'égout, les chambres de visite et une éventuelle fosse septique',
        why: 'Soulevez le couvercle de la chambre de visite si possible. De l\'eau stagnante ou des boues signalent un bouchon partiel ou une canalisation effondrée - une réparation qui implique de creuser le jardin ou l\'allée. S\'il y a une fosse septique, demandez sa dernière vidange et si la rue dispose d\'un égout.'
    },
    'plumbing-8': {
        text: 'Vérifier s\'il existe un réseau séparatif eaux de pluie / eaux usées',
        why: 'Les communes imposent de plus en plus la séparation des eaux pluviales et usées, et lient cette obligation à vos travaux. Poser un réseau séparé après coup dans un jardin existant est perturbant et coûte généralement plusieurs milliers d\'euros.'
    },
    'plumbing-9': {
        text: 'Vérifier où va réellement l\'eau de pluie (infiltration, citerne, égout ou chez le voisin)',
        why: 'Des descentes qui se déversent au pied de la fondation sont une cause majeure de murs humides et de caves mouillées. De l\'eau de pluie délibérément dirigée vers la parcelle voisine est aussi un litige classique. Suivez les tuyaux des yeux : cela prend deux minutes.'
    },
    'plumbing-10': {
        text: 'Contrôler la pente correcte des évacuations visibles',
        why: 'Les évacuations ont besoin d\'une pente constante. Trop plate, les matières se déposent et bouchent ; trop raide, l\'eau devance les matières avec le même résultat. Des bouchons récurrents dans une maison trahissent généralement un défaut d\'installation, pas de la malchance.'
    },
    'plumbing-11': {
        text: 'Chercher les taches d\'humidité sur les murs et plafonds de toute la maison',
        why: 'Repérez chaque tache et demandez-vous ce qui se trouve juste au-dessus. Une tache sous une salle de bain est une fuite de plomberie ; sous une noue ou une cheminée, une infiltration ; en bas d\'un mur, une humidité ascensionnelle. Une peinture fraîche sur une seule partie d\'un plafond est un signal d\'alerte.'
    },
    'plumbing-12': {
        text: 'Tester tous les robinets (gouttes) et vérifier les vannes d\'isolement',
        why: 'Un robinet qui goutte est anodin en soi, mais une maison pleine de robinets qui gouttent révèle le niveau d\'entretien auquel vous pouvez vous attendre ailleurs. L\'absence de vannes d\'isolement signifie que chaque petite réparation coupe l\'eau de toute la maison.'
    },
    'plumbing-13': {
        text: 'Contrôler le compteur d\'eau : tourne-t-il alors que tout est fermé ?',
        why: 'Fermez tous les robinets et observez le compteur pendant cinq minutes. Tout mouvement signale une fuite cachée quelque part dans le bien - peut-être sous un sol ou dans un mur, où elle cause peut-être déjà des dégâts depuis des mois.'
    },
    'plumbing-14': {
        text: 'Vérifier la présence, le raccordement et le fonctionnement d\'une citerne d\'eau de pluie',
        why: 'Une citerne présente mais jamais raccordée aux WC et aux robinets extérieurs n\'apporte rien. Contrôlez la pompe, le filtre et l\'appoint sur le réseau - et ne raccordez jamais l\'eau de pluie au réseau d\'eau potable, ce qui est illégal et dangereux.'
    },
    'plumbing-15': {
        text: 'Demander l\'attestation de contrôle de l\'évacuation privée des eaux',
        why: 'En Flandre, ce contrôle est obligatoire pour une construction ou reconstruction, pour un nouveau raccordement ou une épuration individuelle, et lorsque la rue reçoit un égout séparatif et que vous devez déconnecter sur votre terrain. L\'attestation prouve que l\'eau de pluie et les eaux usées sont correctement séparées et raccordées. Si elle manque ou indique « non conforme », la mise en ordre est à votre charge, et une attestation de plus de 5 ans ne vous dispense plus lors d\'une déconnexion imposée.'
    },
    'plumbing-16': {
        text: 'Localiser le dispositif d\'infiltration : puits, caissons (infiltratiekrat) ou noue',
        why: 'Depuis octobre 2023, le règlement flamand sur l\'eau de pluie impose que celle-ci s\'infiltre sur votre propre parcelle, via un puits d\'infiltration, des caissons enterrés ou une cuvette plantée peu profonde. Demandez où il se trouve et s\'il fonctionne encore : les caissons se colmatent et cessent de drainer. S\'il n\'y en a pas et que vous prévoyez une terrasse, une allée, une annexe ou une piscine, vous devrez en installer un - et le faire après coup à travers un jardin fini est la solution coûteuse.'
    },
    'plumbing-17': {
        text: 'Vérifier la présence d\'un puits de décantation ou d\'un dessableur avant l\'infiltration ou l\'égout',
        why: 'Un puits de décantation retient le sable, les feuilles et les graviers avant qu\'ils n\'atteignent le dispositif d\'infiltration ou l\'égout. Si personne ne l\'a vidé depuis des années, il est plein et tout ce qui se trouve en aval - les caissons, le puits d\'infiltration, le raccordement - se colmate également. Soulevez le couvercle : vous devez voir surtout de l\'eau, pas de la boue.'
    },
    'plumbing-18': {
        text: 'Demander à la commune le plan de zonage : égout, épuration individuelle ou fosse septique',
        why: 'Le plan de zonage communal détermine si le bien se raccorde à l\'égout public ou doit épurer lui-même ses eaux usées avec une installation individuelle, et si une fosse septique est requise. Acheter dans une zone où l\'égout n\'arrivera jamais signifie que l\'épuration individuelle est à votre charge : une installation de plusieurs milliers d\'euros, plus un entretien permanent.'
    },

    /* ---------------- Électricité ---------------- */
    'electrical-0': {
        text: 'Vérifier la présence et la validité du rapport de contrôle, et le lire entièrement',
        why: 'Obligatoire à la vente, valable 25 ans. Un rapport « non conforme » vous donne 18 mois après l\'acte pour corriger tout ce qui y figure. Lisez les infractions vous-même : elles vont d\'un couvercle manquant à une installation à remplacer entièrement, soit plusieurs milliers d\'euros d\'écart.'
    },
    'electrical-1': {
        text: 'Inspecter le tableau électrique - type, âge et étiquetage',
        why: 'Des fusibles à vis en porcelaine, un panneau de bois ou un enchevêtrement de câbles non étiquetés signifient une installation vieille de plusieurs décennies et presque certainement non conforme. Un tableau moderne, bien étiqueté et équipé de disjoncteurs est l\'un des meilleurs signes d\'une maison entretenue.'
    },
    'electrical-2': {
        text: 'Vérifier la puissance du raccordement et son adéquation à vos projets',
        why: 'Cuisson à induction, pompe à chaleur, borne de recharge et panneaux solaires demandent chacun de la puissance. Renforcer le raccordement, voire passer en triphasé, est une intervention du gestionnaire de réseau avec un coût réel et un délai : vérifiez-le avant de planifier une rénovation tout électrique.'
    },
    'electrical-3': {
        text: 'Vérifier la présence du différentiel et le tester',
        why: 'Le différentiel est ce qui empêche une électrocution d\'être mortelle. Appuyez sur le bouton test : il doit déclencher immédiatement. Un différentiel absent, bloqué ou hors service est l\'un des défauts les plus dangereux qu\'un logement puisse avoir.'
    },
    'electrical-4': {
        text: 'Vérifier la présence d\'un différentiel haute sensibilité pour les locaux humides',
        why: 'Salles de bain et cuisines exigent une protection supplémentaire, car l\'eau réduit fortement la résistance du corps. C\'est une exigence standard de la réglementation belge et un point standard des rapports de contrôle.'
    },
    'electrical-5': {
        text: 'Tester les prises - mise à la terre, polarité et fixation',
        why: 'Un testeur de prise coûte une quinzaine d\'euros et contrôle toutes les prises en quelques minutes. Une prise sans terre permet à la carcasse métallique d\'un appareil de devenir sous tension. Des prises qui bougent quand vous retirez une fiche trahissent une mauvaise fixation et peut-être des conducteurs desserrés derrière.'
    },
    'electrical-6': {
        text: 'Vérifier le nombre de circuits et de prises par pièce',
        why: 'Les anciennes installations belges alimentent souvent tout un étage depuis un seul circuit. Cela disjoncte en permanence avec les charges modernes et échauffe le câble. Ajouter des circuits implique des travaux au tableau et de nouveaux câbles dans des murs finis.'
    },
    'electrical-7': {
        text: 'Vérifier si d\'anciennes prises non reliées à la terre sont encore utilisées',
        why: 'Des prises sans terre signifient presque toujours qu\'il n\'y a pas de conducteur de terre dans cette partie de l\'installation : remplacer la prise ne résout donc rien. Cela annonce généralement le recâblage au moins de ce circuit, souvent de toute la maison.'
    },
    'electrical-8': {
        text: 'Inspecter le câblage visible - pas de câble sous tissu ni cassant',
        why: 'Les isolants en caoutchouc et tissu d\'avant 1970 environ deviennent cassants et s\'effritent dès qu\'on y touche, mettant les conducteurs à nu. En trouver en cave ou au grenier, c\'est connaître l\'âge réel de l\'installation, quoi qu\'en dise le vendeur.'
    },
    'electrical-9': {
        text: 'Tester tous les interrupteurs et repérer les connexions improvisées',
        why: 'Des boîtes de dérivation cachées derrière un meuble, des raccords scotchés ou des connecteurs qui traînent dans un faux plafond sont des risques d\'incendie et un signe de bricolage. Si vous voyez de l\'improvisation là où c\'est visible, supposez le pire là où ça ne l\'est pas.'
    },
    'electrical-10': {
        text: 'Contrôler sonnette, parlophone et éventuelle alarme ou caméra',
        why: 'Détails mineurs, mais ils révèlent si le câblage a été étendu proprement ou improvisé. Dans un appartement, un parlophone hors service est une charge commune impliquant le syndic.'
    },
    'electrical-11': {
        text: 'Vérifier les détecteurs de fumée à chaque niveau et leur date de péremption',
        why: 'Légalement obligatoires en Flandre à chaque étage. Les détecteurs expirent, généralement après 10 ans, et un exemplaire périmé ne protège plus. Cela fait aussi partie des normes de qualité du logement, ce qui compte si vous mettez un jour le bien en location.'
    },
    'electrical-12': {
        text: 'Vérifier la présence d\'un détecteur de CO là où il y a un appareil à combustion',
        why: 'Le monoxyde de carbone est incolore et inodore et tue encore chaque hiver en Belgique. Tout appareil au gaz, au mazout, au bois ou au charbon justifie un détecteur : ils coûtent une trentaine d\'euros et constituent l\'équipement de sécurité le moins cher de la maison.'
    },
    'electrical-13': {
        text: 'Contrôler la liaison équipotentielle, surtout dans la salle de bain',
        why: 'La liaison équipotentielle met toutes les parties métalliques au même potentiel, pour qu\'un défaut ne crée pas une différence de tension mortelle entre un robinet et un radiateur. C\'est un point de contrôle standard, et son absence est un motif fréquent de rapport non conforme.'
    },
    'electrical-14': {
        text: 'Vérifier le type de compteur, la présence d\'un compteur digital et d\'une installation solaire',
        why: 'Un compteur digital, une installation photovoltaïque existante et l\'âge de son onduleur influencent vos futures factures et la valeur des panneaux. Demandez les attestations d\'installation et l\'âge de l\'onduleur : un onduleur dure généralement 10 à 15 ans, les panneaux bien plus.'
    },

    /* ---------------- Structure & stabilité ---------------- */
    'structural-0': {
        text: 'Contrôler les murs : fissures, bombements ou dévers',
        why: 'Toutes les fissures ne comptent pas, mais le motif, oui. Des microfissures fines et stables dans l\'enduit sont normales. Des fissures diagonales ou en escalier traversant la maçonnerie, plus larges qu\'environ 2 mm, traversant un linteau, ou un mur visiblement hors d\'aplomb, signalent un mouvement qui exige un ingénieur.'
    },
    'structural-1': {
        text: 'Inspecter les fissures autour des fenêtres et des portes - indice de tassement',
        why: 'Les baies sont les points faibles d\'un mur : le tassement s\'y manifeste en premier. Des fissures diagonales partant des angles de plusieurs baies du même côté de la maison indiquent un mouvement de fondation, pas un retrait d\'enduit.'
    },
    'structural-2': {
        text: 'Identifier les murs porteurs',
        why: 'C\'est ce qui décide si votre projet d\'espace ouvert est un travail de week-end ou une poutre acier calculée à 15 000 EUR avec permis. Frappez le mur, observez le sens des solives et consultez les plans - et ne vous fiez jamais à la parole de l\'agent.'
    },
    'structural-3': {
        text: 'Vérifier si les transformations passées ont été faites avec ingénieur et permis',
        why: 'Murs supprimés, baies agrandies et bois de charpente coupés sans calcul sont fréquents et dangereux. Demandez l\'étude de stabilité et le permis. Sans eux, vous héritez du risque et de la responsabilité, et votre assureur peut refuser un sinistre.'
    },
    'structural-4': {
        text: 'Contrôler les planchers : planéité, souplesse et grincements',
        why: 'Une bille qui roule, des portes qui s\'ouvrent seules et un plancher qui rebondit quand on marche signalent une flexion des solives, une pourriture aux appuis ou un tassement de fondation. Testez au milieu de la portée, pas contre le mur.'
    },
    'structural-5': {
        text: 'Vérifier la capacité portante du plancher pour l\'usage prévu',
        why: 'Un carrelage lourd, un grand aquarium, une salle de sport, une baignoire ou une toiture verte ajoutent une charge importante. Les vieux planchers en bois n\'ont pas été conçus pour cela, et le découvrir après coup implique d\'ouvrir le plafond du dessous.'
    },
    'structural-6': {
        text: 'Contrôler les poutres en bois : pourriture, vrillettes et appuis dans le mur',
        why: 'Les poutres en bois cèdent presque toujours à l\'endroit où elles reposent dans le mur extérieur, parce que c\'est là que l\'humidité s\'accumule et là que vous ne pouvez pas voir. Cherchez des traces d\'humidité sur le mur sous les appuis, et enfoncez un tournevis dans tout bois suspect.'
    },
    'structural-7': {
        text: 'Inspecter les plafonds : fissures, affaissement ou enduit décollé',
        why: 'Un plafond qui s\'affaisse peut signifier que l\'enduit a perdu son accrochage sur le lattis (fréquent dans les maisons anciennes et dangereux car il peut tomber), qu\'il y a une fuite au-dessus, ou que les solives sont surchargées. Poussez doucement vers le haut : si ça bouge, c\'est déjà décollé.'
    },
    'structural-8': {
        text: 'Vérifier que les hauteurs sous plafond respectent les normes d\'habitabilité',
        why: 'Les normes de qualité du logement fixent des hauteurs minimales pour les pièces habitables. En dessous, une pièce ne peut légalement pas compter comme chambre ou séjour, ce qui affecte la location, l\'assurance et la revente - et isoler le sol réduit encore la hauteur.'
    },
    'structural-9': {
        text: 'Vérifier l\'équerrage des châssis de portes et de fenêtres',
        why: 'Posez un niveau sur quelques châssis et essayez chaque porte. Des châssis hors d\'équerre dans toute la maison, surtout d\'un même côté, sont un indice de tassement bon marché et fiable, facile à vérifier pendant une visite.'
    },
    'structural-10': {
        text: 'Contrôler la stabilité de l\'escalier, des marches et des rampes',
        why: 'L\'escalier est l\'endroit où surviennent les accidents domestiques les plus graves. Des marches désolidarisées, une rampe qui bouge, des hauteurs de marche inégales ou un garde-corps manquant sont à la fois un problème de sécurité et une infraction aux normes du logement.'
    },
    'structural-11': {
        text: 'Contrôler les dimensions et l\'échappée de l\'escalier',
        why: 'Les escaliers raides et étroits à hautes marches sont fréquents dans les maisons de rangée belges. En poser un conforme aux normes actuelles consomme de la surface sur deux niveaux : c\'est un chantier bien plus lourd qu\'il n\'y paraît - et cela détermine aussi si vos meubles pourront monter.'
    },
    'structural-12': {
        text: 'Chercher les signes de tassement - sols en pente, seuils inégaux, jeux',
        why: 'Le tassement se manifeste par un faisceau d\'indices plutôt que par une fissure : sols en pente, jeux entre plinthe et sol, portes qui coincent d\'un côté, et fissures qui penchent toutes dans le même sens. Ensemble, ils justifient une expertise de stabilité avant de vous engager.'
    },
    'structural-13': {
        text: 'Identifier le type et l\'état de la fondation là où elle est visible',
        why: 'Les maisons belges anciennes reposent souvent sur des semelles de brique peu profondes sans membrane d\'étanchéité. Ce n\'est pas automatiquement un problème, mais cela explique l\'humidité ascensionnelle et conditionne ce qui est possible si vous voulez étendre, creuser ou reprendre en sous-œuvre.'
    },
    'structural-14': {
        text: 'Contrôler poutres, colonnes et étais ajoutés par un ancien propriétaire',
        why: 'Un étai métallique réglable laissé « temporairement » dans une cave signale que quelqu\'un savait qu\'il y avait un problème. Des about de poutres acier corrodés dans une maçonnerie humide en sont un autre : ils gonflent en rouillant et fissurent le mur autour.'
    },
    'structural-15': {
        text: 'Vérifier l\'existence et l\'état des murs mitoyens',
        why: 'Dans le bâti belge en rangée, le mur mitoyen est une propriété partagée, et y intervenir engage juridiquement et financièrement votre voisin. Un mur mitoyen penché ou fissuré, ou un immeuble voisin à l\'abandon, devient aussi votre problème.'
    },
    'structural-16': {
        text: 'Mesurer la fissure la plus large et repérer le schéma diagonal des dégâts de sécheresse',
        why: 'Après une série d\'étés secs, le retrait des sols argileux sous les fondations est devenu l\'une des causes de dégâts qui progressent le plus vite en Belgique. Le schéma typique : des fissures diagonales partant des angles des baies, plus larges à une extrémité. Photographiez la fissure avec une pièce de monnaie ou une règle à côté : au-delà de 3 mm, elle est officiellement significative, et une expertise de stabilité avant signature vaut son prix.'
    },
    'structural-17': {
        text: 'Vérifier si l\'adresse se situe sur des sols plastiques (argile gonflante)',
        why: 'La Databank Ondergrond Vlaanderen publie une carte gratuite montrant où le sous-sol est sensible au gonflement et au retrait de l\'argile. Rechercher l\'adresse prend une minute et vous indique si les fissures que vous observez ont une cause plausible - et si le risque subsiste pour l\'extension que vous envisagiez.'
    },
    'structural-18': {
        text: 'Noter les grands arbres proches de la façade et demander quand ils ont été plantés ou abattus',
        why: 'Un arbre adulte peut prélever des dizaines de litres d\'eau par jour dans le sol en été, précisément là où repose la fondation, ce qui fait retirer l\'argile. Abattre un grand arbre peut être tout aussi dommageable : le sol reprend lentement de l\'eau et gonfle à nouveau. Les deux se manifestent des années plus tard par des fissures : l\'historique compte donc.'
    },

    /* ---------------- Chauffage & ventilation ---------------- */
    'hvac-0': {
        text: 'Contrôler l\'âge, la marque et l\'état de la chaudière',
        why: 'Lisez la plaque signalétique. Une chaudière de plus de 15 à 20 ans est en fin de vie et ses pièces se raréfient. Le remplacement, ou le passage à une pompe à chaleur, représente généralement 5 000 à 15 000 EUR : l\'un des plus gros coûts après l\'achat, et un argument de négociation légitime.'
    },
    'hvac-1': {
        text: 'Vérifier s\'il s\'agit d\'une chaudière à condensation',
        why: 'Les chaudières à condensation récupèrent la chaleur des fumées et consomment sensiblement moins. Une chaudière non condensante est non seulement peu efficace, elle indique aussi que le système de chauffage n\'a pas été modernisé : radiateurs et régulation sont généralement anciens eux aussi.'
    },
    'hvac-2': {
        text: 'Contrôler le type de chauffage (mazout/gaz/électrique) et le coût d\'une conversion',
        why: 'Le mazout exige une citerne, un entretien annuel et comporte un risque de pollution du sol ; le chauffage électrique direct est très coûteux à l\'usage. Changer de combustible implique un nouvel appareil, un nouveau conduit, éventuellement un raccordement au gaz, et l\'enlèvement ou la neutralisation de l\'ancienne citerne.'
    },
    'hvac-3': {
        text: 'Inspecter la pompe à chaleur si présente - type, âge et adéquation du logement',
        why: 'Une pompe à chaleur n\'est performante que dans un logement bien isolé, avec des émetteurs basse température (chauffage au sol ou radiateurs surdimensionnés). Installée dans une maison mal isolée avec de petits radiateurs, elle produit des factures élevées et des propriétaires déçus.'
    },
    'hvac-4': {
        text: 'Tester le chauffage dans chaque pièce, thermostat compris',
        why: 'Demandez à allumer le chauffage, même en été. Des radiateurs qui restent froids, froids en bas (boues) ou chauds seulement près de la chaudière révèlent un système à équilibrer, à désembouer ou à réparer. C\'est le seul moyen de voir la vérité sur l\'installation.'
    },
    'hvac-5': {
        text: 'Contrôler les radiateurs : état, dimensionnement et vannes',
        why: 'Des traces de rouille, des vannes qui fuient ou des radiateurs manifestement trop petits pour la pièce impliquent un coût dans les deux cas : les remplacer, ou vivre dans une maison qui n\'est jamais vraiment chaude. Des vannes thermostatiques sur chaque radiateur sont une économie simple et efficace si elles manquent.'
    },
    'hvac-6': {
        text: 'Vérifier le chauffage au sol - zones, collecteur et régulation',
        why: 'Le chauffage au sol est excellent avec une pompe à chaleur, mais une fuite ou un bouchon dans une boucle noyée est très difficile à réparer. Demandez le plan de récolement montrant le tracé des boucles : vous en aurez besoin la première fois que vous voudrez percer le sol.'
    },
    'hvac-7': {
        text: 'Demander l\'attestation d\'entretien de l\'installation de chauffage',
        why: 'L\'entretien est une obligation légale (en Flandre : annuel au mazout, tous les 2 ans au gaz). Des attestations manquantes signifient un risque de CO, une consommation plus élevée et un possible refus de votre assureur incendie. Les rapports révèlent aussi ce qui a déjà posé problème.'
    },
    'hvac-8': {
        text: 'Vérifier le type de ventilation (A, C ou D) et son fonctionnement',
        why: 'Une famille produit environ 10 litres de vapeur d\'eau par jour. Dans une maison étanche et isolée sans ventilation efficace, cette humidité devient moisissure en un seul hiver. Mettez le système en marche et placez une feuille de papier contre les bouches d\'extraction : elle doit tenir.'
    },
    'hvac-9': {
        text: 'Contrôler la ventilation double flux - filtres et conduits',
        why: 'Un groupe double flux ne fonctionne que si les filtres sont remplacés et les conduits propres. Filtres colmatés et conduits jamais nettoyés sont fréquents et transforment un système efficace en un système bruyant, sale et inefficace. Demandez la date du dernier nettoyage des conduits.'
    },
    'hvac-10': {
        text: 'Inspecter les grilles de ventilation dans chaque pièce',
        why: 'Des grilles scotchées, repeintes ou bourrées de tissu montrent que les occupants luttaient contre les courants d\'air ou le bruit. L\'humidité qui aurait dû sortir par ces grilles se trouve maintenant dans les murs, l\'isolant ou le mobilier.'
    },
    'hvac-11': {
        text: 'Contrôler la climatisation si présente, et le risque de surchauffe estivale',
        why: 'Les étés belges se réchauffent et les maisons bien isolées avec de grandes surfaces vitrées au sud ou à l\'ouest surchauffent fortement. Regardez s\'il existe une protection solaire extérieure : poser des volets ou des screens est bien plus efficace et moins cher qu\'ajouter du froid.'
    },
    'hvac-12': {
        text: 'Contrôler la citerne à mazout - âge, emplacement, attestation et fuites',
        why: 'Les citernes enterrées et en cave sont soumises à des règles strictes et à des contrôles périodiques. Une citerne qui fuit devient un dossier de pollution du sol dont l\'assainissement peut coûter des dizaines de milliers d\'euros, et une citerne hors service doit être vidée, nettoyée et certifiée, pas simplement abandonnée.'
    },
    'hvac-13': {
        text: 'Vérifier l\'installation gaz et l\'attestation de raccordement',
        why: 'Les fuites de gaz et les appareils mal évacués provoquent explosions et intoxications au CO. Vérifiez que les flexibles sont dans leur date, que le local dispose d\'une ventilation permanente et qu\'une attestation de conformité existe.'
    },
    'hvac-14': {
        text: 'Demander l\'historique d\'entretien, les manuels et les coordonnées de l\'installateur',
        why: 'Un historique complet montre que l\'installation a été soignée et vous donne un technicien qui connaît déjà le système. Aucun document signifie généralement aucun entretien : partez du pire et intégrez-le à votre offre.'
    },
    'hvac-15': {
        text: 'Contrôler le type de conduit de fumée et sa compatibilité avec un appareil moderne',
        why: 'Une chaudière à condensation moderne exige un conduit différent de celui d\'un ancien appareil atmosphérique, et une vieille cheminée maçonnée doit généralement être tubée. Ce tubage est un coût réel que l\'on découvre souvent après avoir commandé la nouvelle chaudière.'
    },

    /* ---------------- Potentiel de rénovation ---------------- */
    'renovation-0': {
        text: 'Vérifier si vos transformations nécessitent un permis',
        why: 'Les règles de permis varient par commune et par zone. Démarrer sans permis peut entraîner un ordre d\'arrêt, une amende et l\'obligation de défaire les travaux. Renseignez-vous auprès de la commune avant d\'acheter si vos projets sont la raison pour laquelle vous voulez ce bien.'
    },
    'renovation-1': {
        text: 'Établir un budget total réaliste avec des devis, pas des estimations',
        why: 'L\'erreur financière la plus fréquente des acheteurs est de sous-estimer une rénovation d\'un facteur deux. Obtenez au moins un vrai devis pour les postes les plus lourds (toiture, électricité, chauffage, isolation) avant votre offre, et prévoyez 15 à 20 % de réserve pour ce que vous ne voyez pas encore.'
    },
    'renovation-2': {
        text: 'Planifier l\'ordre des travaux - isolation et étanchéité à l\'air avant les finitions',
        why: 'Un mauvais ordre, c\'est payer deux fois : un enduit neuf avant le recâblage, une cuisine neuve avant la toiture, ou de nouvelles fenêtres avant l\'isolation. Planifiez d\'abord l\'enveloppe, ensuite les techniques, et seulement après les finitions.'
    },
    'renovation-3': {
        text: 'Vérifier la faisabilité de l\'isolation de la toiture plate - par l\'extérieur ou l\'intérieur',
        why: 'Isoler une toiture plate par l\'extérieur est la bonne méthode et implique généralement une nouvelle membrane en même temps. Isoler par l\'intérieur coûte moins cher mais emprisonne l\'humidité dans le support et peut le faire pourrir. Ce choix détermine s\'il faut aussi rehausser coupoles, portes et relevés.'
    },
    'renovation-4': {
        text: 'Vérifier si l\'isolation extérieure affecte les seuils et l\'accès à la toiture',
        why: 'Ajouter 12 à 20 cm sur une toiture plate ou une terrasse relève le niveau fini : les portes donnant sur ce toit risquent de ne plus s\'ouvrir et la hauteur de relevé passe sous le minimum requis. C\'est une mauvaise surprise classique et coûteuse en cours de chantier.'
    },
    'renovation-5': {
        text: 'Vérifier que la rehausse des coupoles est prévue au budget',
        why: 'Après une isolation par l\'extérieur, le relevé de la coupole doit encore dépasser suffisamment de la toiture finie, sinon l\'eau y entre directement. Rehausser coupoles et lanterneaux est un travail spécialisé que les devis omettent souvent discrètement.'
    },
    'renovation-6': {
        text: 'Évaluer l\'isolation de façade - extérieure, coulisse ou intérieure',
        why: 'L\'isolation extérieure est la plus performante et supprime les ponts thermiques, mais change l\'aspect et peut exiger un permis. Le remplissage de coulisse est le moins cher si la coulisse s\'y prête. L\'isolation intérieure est la plus risquée : mal détaillée, elle déplace le point de condensation dans le mur et provoque humidité et pourriture invisibles.'
    },
    'renovation-7': {
        text: 'Vérifier si la coulisse convient à une isolation par injection',
        why: 'La coulisse doit être assez large, propre, sèche et exempte de ponts de mortier. Injecter une coulisse humide ou encombrée de gravats crée des taches d\'humidité permanentes à l\'intérieur. Une inspection à l\'endoscope avant injection coûte peu et évite un résultat très désagréable.'
    },
    'renovation-8': {
        text: 'Vérifier si l\'isolation intérieure est possible sans perdre d\'espace critique',
        why: 'L\'isolation intérieure coûte généralement 8 à 14 cm sur chaque mur extérieur. Dans une petite maison de rangée belge, cela peut rendre une chambre inutilisable, et elle déplace radiateurs, prises et ébrasements - autant de coûts que le devis ne mentionne pas toujours.'
    },
    'renovation-9': {
        text: 'Vérifier la faisabilité de l\'isolation du sol et son effet sur la hauteur sous plafond',
        why: 'Isolation de sol plus chape prend 10 à 15 cm. Cela peut faire passer la hauteur sous le minimum habitable, vous obliger à raccourcir chaque porte intérieure, et modifier le niveau à la porte d\'entrée et à l\'escalier. Mesurez avant de vous engager.'
    },
    'renovation-10': {
        text: 'Contrôler l\'accessibilité, la hauteur et la sécheresse du vide sanitaire',
        why: 'Un vide sanitaire accessible et sec rend l\'isolation du sol et les réparations de conduites peu coûteuses. Un vide humide, bas ou inaccessible signifie que la seule voie passe par le dessus, donc par la dépose de tout le sol. Regardez à la lampe s\'il y a une trappe.'
    },
    'renovation-11': {
        text: 'Vérifier si le remplacement des châssis est nécessaire pour le label PEB visé',
        why: 'Les châssis sont généralement le deuxième poste de rénovation énergétique après la toiture. Si une obligation flamande de rénovation s\'applique, faites modéliser quelles mesures vous amènent réellement au label D : parfois toiture et murs suffisent et les fenêtres peuvent attendre quelques années.'
    },
    'renovation-12': {
        text: 'Évaluer le potentiel d\'aménagement du grenier',
        why: 'Aménager un grenier est le moyen le moins cher d\'ajouter une pièce - mais seulement si hauteur, plancher, escalier, lumière et issue de secours le permettent déjà. S\'il faut créer l\'un de ces éléments, le coût au mètre carré peut dépasser celui d\'une extension.'
    },
    'renovation-13': {
        text: 'Vérifier si une surélévation ou une lucarne est autorisée ici',
        why: 'Les règles communales sur les volumes de toiture, la largeur des lucarnes et l\'aspect côté rue varient énormément. Acheter en supposant que l\'on pourra surélever la toiture, sans vérifier la réglementation locale, est l\'une des suppositions les plus coûteuses qui soient.'
    },
    'renovation-14': {
        text: 'Vérifier si l\'aménagement de la cave est réaliste',
        why: 'Les aménagements de cave échouent sur trois points : la hauteur, l\'humidité et la lumière. Abaisser le sol d\'une cave implique de reprendre les fondations en sous-œuvre, un travail d\'ingénierie lourd. Assurez-vous que votre ambition correspond au bâtiment avant de payer la maison.'
    },
    'renovation-15': {
        text: 'Vérifier qu\'une extension respecte les règles de parcelle et les reculs',
        why: 'Les reculs par rapport aux limites, la surface bâtie maximale, la profondeur par rapport aux voisins et les règles d\'infiltration des eaux pluviales limitent tous ce que vous pouvez construire. Les fenêtres des voisins comptent aussi juridiquement. Renseignez-vous auprès de la commune, pas du vendeur.'
    },
    'renovation-16': {
        text: 'Évaluer la complexité d\'une rénovation de salle de bain',
        why: 'Une salle de bain paraît cosmétique mais c\'est la pièce la plus technique de la maison : étanchéité, pentes, ventilation, électricité en volumes humides et évacuations doivent tous être corrects. Bâcler ici, c\'est produire exactement les fuites que le prochain propriétaire trouvera.'
    },
    'renovation-17': {
        text: 'Vérifier si la rénovation de la cuisine impose de déplacer plomberie ou évacuations',
        why: 'Garder l\'évier et les appareils à leur place maintient une rénovation de cuisine abordable. Les déplacer, surtout dans une dalle en béton, ajoute plusieurs milliers d\'euros. Décidez de votre implantation avant d\'évaluer la cuisine que vous achetez.'
    },
    'renovation-18': {
        text: 'Vérifier si la plomberie doit être entièrement remplacée',
        why: 'Les conduites en plomb doivent disparaître, et l\'acier galvanisé suit généralement de près. Remplacer la tuyauterie coûte bien moins cher pendant que murs et sols sont déjà ouverts : cela appartient à la première phase d\'une rénovation, pas à la dernière.'
    },
    'renovation-19': {
        text: 'Vérifier si un recâblage complet est nécessaire',
        why: 'Un recâblage implique de saigner chaque mur puis de tout refinir : il doit donc précéder toute finition. Le combiner avec l\'isolation et l\'enduisage fait économiser beaucoup ; le faire après, c\'est payer deux fois les mêmes murs.'
    },
    'renovation-20': {
        text: 'Évaluer le nettoyage de façade, le rejointoyage et la réparation des briques',
        why: 'Rejointoyer une façade moyenne représente environ 40 à 80 EUR/m2 échafaudage compris : une maison entière est donc un vrai poste budgétaire. Ce n\'est pas optionnel si les joints sont ouverts : l\'eau dans le mur annule toutes vos autres améliorations.'
    },
    'renovation-21': {
        text: 'Vérifier si une cheminée peut être supprimée ou doit être conservée',
        why: 'Supprimer une cheminée libère de la surface, mais la souche peut être porteuse, partagée avec un voisin, ou nécessaire comme conduit de ventilation ou de fumée. Dans un ensemble protégé, la partie visible doit parfois rester. Vérifiez-le avant de dessiner votre plan autour.'
    },
    'renovation-22': {
        text: 'Évaluer le potentiel photovoltaïque : orientation, ombrage et état de la toiture',
        why: 'Le sud est optimal, l\'est-ouest reste bon, le nord n\'en vaut pas la peine. Cheminées, arbres et immeubles voisins peuvent détruire le rendement de toute une chaîne. Surtout : ne posez jamais de panneaux sur une toiture à renouveler dans les 10 ans - les déposer et les reposer coûte des milliers d\'euros.'
    },
    'renovation-23': {
        text: 'Vérifier que la charpente peut porter des panneaux solaires ou une toiture verte',
        why: 'Les panneaux ajoutent du poids et une charge au vent ; une toiture verte bien davantage, surtout gorgée d\'eau. Sur une charpente ancienne, cela doit être validé par un ingénieur : c\'est précisément le type de surcharge qui fait affaisser un faîte avec le temps.'
    },
    'renovation-24': {
        text: 'Prévoir le budget de désamiantage si nécessaire',
        why: 'La rénovation est le déclencheur qui transforme « amiante présent » en « amiante à retirer par une entreprise certifiée ». Faites chiffrer ce poste séparément et tôt, car il conditionne aussi l\'ordre et l\'organisation de tout le reste du chantier.'
    },
    'renovation-25': {
        text: 'Vérifier les primes, prêts et taux de TVA disponibles avant de commencer',
        why: 'Les primes régionales, les prêts à taux réduit et le taux de TVA réduit pour les logements anciens peuvent changer substantiellement votre budget - mais la plupart des dispositifs exigent une demande AVANT les travaux ou le recours à des entrepreneurs enregistrés. Demander après, c\'est généralement perdre l\'argent.'
    },

    /* ---------------- Appartement ---------------- */
    'apartment-0': {
        text: 'Demander les informations du syndic et l\'acte de base',
        why: 'L\'acte de base définit exactement ce qui vous appartient en privatif, ce qui est commun, et votre quote-part dans chaque charge. Il contient aussi des restrictions sur les animaux, la location de courte durée, l\'usage professionnel et les modifications de terrasse, que vous ne pouvez pas changer seul.'
    },
    'apartment-1': {
        text: 'Lire les procès-verbaux des trois dernières assemblées générales',
        why: 'C\'est là que se trouve l\'état réel de l\'immeuble : travaux votés, litiges, charges impayées et décisions reportées. Une rénovation de façade ou de toiture décidée peut représenter 10 000 à 40 000 EUR par lot, et c\'est la date de la décision - pas celle de votre achat - qui détermine généralement qui paie.'
    },
    'apartment-2': {
        text: 'Examiner les charges communes et ce qu\'elles comprennent',
        why: 'Les charges mensuelles varient énormément et constituent une part permanente de votre coût de logement. Vérifiez si chauffage, eau, entretien de l\'ascenseur, nettoyage, assurance et honoraires du syndic sont inclus, et comparez le montant au budget réel de l\'immeuble plutôt qu\'à l\'annonce.'
    },
    'apartment-3': {
        text: 'Vérifier le solde du fonds de réserve au regard de l\'âge de l\'immeuble',
        why: 'Un fonds de réserve presque vide dans un immeuble de 40 ans signifie que la prochaine grosse réparation deviendra immédiatement un appel de fonds auprès des copropriétaires. Un fonds sain est l\'un des meilleurs signes d\'une copropriété bien gérée.'
    },
    'apartment-4': {
        text: 'Vérifier les gros travaux planifiés ou décidés',
        why: 'Rénovation de façade, remplacement de toiture, modernisation d\'ascenseur, remplacement du chauffage collectif et rénovation énergétique de l\'enveloppe commune sont les gros postes. Demandez explicitement si l\'un d\'eux a été voté, estimé ou reporté : une décision reportée est une facture en attente.'
    },
    'apartment-5': {
        text: 'Contrôler l\'âge de l\'ascenseur, sa modernisation et son attestation de contrôle',
        why: 'Les ascenseurs belges doivent être modernisés pour répondre aux exigences de sécurité, et une modernisation complète représente une charge commune très lourde. Consultez le dernier rapport de contrôle et vérifiez si la modernisation est faite, budgétée, ou encore reportée.'
    },
    'apartment-6': {
        text: 'Inspecter les parties communes : hall, cage d\'escalier, toiture et caves',
        why: 'L\'état des parties communes est l\'indicateur le plus honnête de la gestion de l\'immeuble. De l\'humidité au parking souterrain, une toiture fatiguée ou une cage d\'escalier qui s\'écaille sont autant de futures factures qui arriveront à votre nom.'
    },
    'apartment-7': {
        text: 'Évaluer l\'isolation acoustique entre appartements et depuis la cage d\'escalier',
        why: 'Le bruit d\'impact venant de l\'appartement du dessus est la première plainte dans les immeubles belges et est pratiquement impossible à corriger de votre côté. Revenez à un autre moment de la journée et demandez si le règlement impose un tapis ou une sous-couche acoustique.'
    },
    'apartment-8': {
        text: 'Vérifier si la terrasse ou le balcon est privatif ou commun',
        why: 'Une terrasse est souvent une partie commune à usage exclusif, ce qui signifie que vous ne pouvez pas modifier seul le revêtement, le garde-corps ou l\'étanchéité - et que les réparations peuvent relever d\'une décision collective. Lisez l\'acte de base, pas la brochure de vente.'
    },
    'apartment-9': {
        text: 'Contrôler les compteurs individuels d\'eau, de chauffage et d\'électricité',
        why: 'Avec un chauffage collectif sans compteurs individuels, vous payez la consommation de vos voisins selon votre quote-part. Cela peut représenter un surcoût permanent et important, et cela supprime toute incitation de l\'immeuble à économiser l\'énergie.'
    },
    'apartment-10': {
        text: 'Vérifier l\'attribution de la cave, du garage ou du parking et s\'ils sont compris',
        why: 'Parking et cave sont souvent vendus comme des lots distincts, avec leur propre prix, leurs taxes et leurs charges. Confirmez les numéros de lot exacts dans l\'acte plutôt que de vous fier à ce qu\'on vous a montré pendant la visite.'
    },
    'apartment-11': {
        text: 'Contrôler le local vélos, les locaux poubelles et les accès',
        why: 'Ce sont les détails du quotidien qui déterminent s\'il est agréable de vivre dans un appartement. Ce sont aussi des sources classiques de conflits en assemblée générale : leur état en dit long sur la copropriété.'
    },
    'apartment-12': {
        text: 'Vérifier l\'année de construction et le PEB du lot et des installations communes',
        why: 'En Flandre, l\'obligation de rénovation s\'applique par unité de logement, mais la toiture, la façade et le chauffage communs relèvent d\'une décision collective. Vous pouvez donc être légalement tenu d\'atteindre le label D tout en dépendant d\'un vote en assemblée générale : vérifiez les deux avant d\'acheter.'
    },
    'apartment-13': {
        text: 'Contrôler la sécurité incendie : détecteurs, issues et compartimentage',
        why: 'Les immeubles à appartements ont des exigences spécifiques de sécurité incendie pour les cages d\'escalier, les portes et la détection. Des issues encombrées, des portes coupe-feu calées et des détecteurs manquants sont à la fois un danger immédiat et un signe de gestion défaillante.'
    },
    'apartment-14': {
        text: 'Vérifier les possibilités internet et TV dans l\'immeuble (coax, fibre)',
        why: 'Dans un appartement, vous ne pouvez pas simplement commander un nouveau raccordement : amener la fibre dans l\'immeuble peut exiger une décision d\'assemblée générale. Vérifiez ce qui est physiquement présent dans le lot et dans la gaine technique.'
    },
    'apartment-15': {
        text: 'Demander s\'il existe des litiges en cours ou des arriérés dans la copropriété',
        why: 'Des procédures judiciaires contre un entrepreneur ou un copropriétaire, et des arriérés importants, affectent les finances de tout l\'immeuble - et donc les vôtres. Le syndic doit fournir cette information : demandez-la explicitement et par écrit.'
    }
};
